import { operation } from "@tinker/core";
import { database } from "./database.ts";
import { currentUser } from "./auth.ts";
import { readTodoCommand } from "../contracts/commands.ts";
import { eventHistory } from "@tinker/start/server";
import type { Todos } from "../contracts/todos.ts";
import type { Sync } from "../contracts/sync.ts";
import { raise } from "../errors.ts";
export const listTodos = operation({
  label: "listTodos",
  depends: { currentUser, database },
  run: async ({ currentUser, database }): Promise<Todos.Row[]> => {
    const [{ asc, eq }, { todo }] = await Promise.all([
      import("drizzle-orm"),
      import("./todos.schema.ts"),
    ]);
    return database
      .select({ id: todo.id, title: todo.title, done: todo.done })
      .from(todo)
      .where(eq(todo.ownerId, currentUser.id))
      .orderBy(asc(todo.id));
  },
});
export const changeTodo = operation({
  label: "changeTodo",
  input: readTodoCommand,
  depends: { currentUser, database, history: eventHistory },
  run: async ({ currentUser, database, history }, { input }) => {
    const [{ and, asc, eq }, { todo }, { execution }] = await Promise.all([
      import("drizzle-orm"),
      import("./todos.schema.ts"),
      import("@tinker/start/server"),
    ]);
    await database.transaction(async (tx) => {
      await history.lock(tx, currentUser.id);
      if (await history.find(tx, input.executionId, currentUser.id)) return;
      const change = input.change;
      let changed = true;
      if (change.kind === "add")
        await tx.insert(todo).values({ ownerId: currentUser.id, title: change.title });
      else {
        const owned = and(eq(todo.id, change.id), eq(todo.ownerId, currentUser.id));
        const row = (await tx.select().from(todo).where(owned)).at(0);
        if (!row) raise("TodoMissing", {});
        if (change.kind === "delete") await tx.delete(todo).where(owned);
        else if (row.done !== change.done)
          await tx.update(todo).set({ done: change.done }).where(owned);
        else changed = false;
      }
      await tx.insert(execution).values({ id: input.executionId, stream: currentUser.id });
      const payloads: Sync.Payload[] = [];
      if (changed) {
        const rows = await tx
          .select({ id: todo.id, title: todo.title, done: todo.done })
          .from(todo)
          .where(eq(todo.ownerId, currentUser.id))
          .orderBy(asc(todo.id));
        payloads.push({ kind: "change", change: { kind: "todos", rows } });
      }
      payloads.push({ kind: "result", result: { kind: "complete", action: "todo" } });
      await history.append(tx, currentUser.id, input.executionId, payloads);
    });
    return { executionId: input.executionId };
  },
});

import { pgTable, integer, text, boolean, index } from "drizzle-orm/pg-core";
import { user } from "./schema.ts";
export const todo = pgTable(
  "todo",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    ownerId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text().notNull(),
    done: boolean().notNull().default(false),
  },
  (table) => [index("todo_owner_id").on(table.ownerId)],
);

import { z } from "zod";
import { raise } from "../errors.ts";
export declare namespace Todos {
  type Row = { id: number; title: string; done: boolean };
  type Change = z.infer<typeof todoChange>;
}
const todoChange = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("add"), title: z.string().trim().min(1).max(200) }).strict(),
  z
    .object({
      kind: z.literal("setDone"),
      id: z.number().int().positive().max(2_147_483_647),
      done: z.boolean(),
    })
    .strict(),
  z
    .object({ kind: z.literal("delete"), id: z.number().int().positive().max(2_147_483_647) })
    .strict(),
]);
/**
 * @param raw - From the todo command or form; why: validate one todo change.
 */
export function readTodoChange(raw: unknown): Todos.Change {
  const result = todoChange.safeParse(raw);
  if (!result.success)
    raise("BadInput", { reason: "Use a title with 1 to 200 characters and a valid todo change." });
  return result.data;
}

import { z } from "zod";
import { data, operation, isError as isCoreError } from "@tinker/core";
import { useData, useRun } from "@tinker/react";
import { Link, Navigate, useRouterState } from "@tanstack/react-router";
import { updateTodo } from "../transport/todos.functions.ts";
import { readTodoChange } from "../contracts/todos.ts";
import { todos, profile } from "./state.ts";
import { syncClient } from "@tinker/start/client";
import { isError } from "../errors.ts";
import { Button } from "./ui/button.tsx";
import { Input } from "./ui/input.tsx";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "./ui/card.tsx";
const flow = data<{ kind: "idle" } | { kind: "saving" } | { kind: "failed"; message: string }>({
  label: "todos.flow",
  initial: { kind: "idle" },
});
const saveTodo = operation({
  label: "todos.save",
  input: readTodoChange,
  depends: { flow: flow.controller, sync: syncClient },
  run: async ({ flow, sync }, { defer, random, input, signal }) => {
    flow.set({ kind: "saving" });
    defer(() => flow.set({ kind: "idle" }));
    const executionId = random.uuid();
    await sync.execute(
      executionId,
      { send: updateTodo, data: { executionId, change: input } },
      signal,
    );
  },
});
const showFailure = operation({
  label: "todos.showFailure",
  input(error: unknown) {
    const cause = isCoreError(error, "DataValidationFailed") ? error.payload.cause : error;
    return isError(cause, "BadInput")
      ? cause.payload.reason
      : "That change did not finish. Try again or reload the page.";
  },
  depends: { flow: flow.controller },
  run: ({ flow }, { input }) => {
    flow.set({
      kind: "failed",
      message: input,
    });
  },
});
const attemptTodo = operation({
  label: "todos.attempt",
  input: z.unknown(),
  depends: { save: saveTodo, failure: showFailure },
  run: async ({ save, failure }, { input }) => {
    const result = await save.settle({ rawInput: input });
    if (result.status === "success") return true;
    if (result.status === "failed") failure.run({ rawInput: result.error });
    else failure.run({ rawInput: undefined });
    return false;
  },
});
export function Todos() {
  const rows = useData(todos);
  const account = useData(profile);
  const loading = useRouterState({ select: (state) => state.isLoading });
  const state = useData(flow);
  const save = useRun(attemptTodo);
  const busy = state.kind === "saving" || loading;
  if (account === null) return <Navigate to="/" />;
  return (
    <main className="mx-auto max-w-2xl px-5 py-8 sm:py-12">
      <header className="mb-8 flex items-center justify-between gap-4">
        <div>
          <p className="text-xs font-semibold tracking-widest text-muted-foreground">
            TINKERED / TODOS
          </p>
          <p className="mt-2 break-all text-sm text-muted-foreground">
            {account.name} · {account.email}
          </p>
        </div>
        <Button asChild variant="outline">
          <Link to="/profile" disabled={busy}>
            Account
          </Link>
        </Button>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>
            <h1>Your private list</h1>
          </CardTitle>
          <CardDescription>Only you can read or change these todos.</CardDescription>
        </CardHeader>
        <CardContent>
          <form
            className="mb-5 flex items-end gap-2"
            onSubmit={async (event) => {
              event.preventDefault();
              const form = event.currentTarget;
              if (
                await save.runAsync({
                  rawInput: { kind: "add", title: new FormData(form).get("title") },
                })
              )
                form.reset();
            }}
          >
            <label className="grid min-w-0 flex-1 gap-2 text-sm font-medium">
              New todo
              <Input
                name="title"
                placeholder="What needs doing?"
                required
                maxLength={200}
                disabled={busy}
              />
            </label>
            <Button disabled={busy}>Add todo</Button>
          </form>
          <p role="alert" className="mb-3 text-sm text-destructive">
            {state.kind === "failed" ? state.message : null}
          </p>
          {rows.length === 0 ? (
            <p className="rounded-lg border border-dashed p-6 text-center text-sm text-muted-foreground">
              Your list is empty. Add your first todo.
            </p>
          ) : (
            <ul className="divide-y">
              {rows.map((row) => (
                <li key={row.id} className="flex items-center gap-3 py-3">
                  <label className="flex min-w-0 flex-1 items-center gap-3 text-sm">
                    <input
                      type="checkbox"
                      checked={row.done}
                      disabled={busy}
                      onChange={(event) =>
                        save.runAsync({
                          rawInput: { kind: "setDone", id: row.id, done: event.target.checked },
                        })
                      }
                      className="size-4 shrink-0 accent-primary"
                    />
                    <span
                      className={
                        row.done
                          ? "min-w-0 break-words text-muted-foreground line-through"
                          : "min-w-0 break-words"
                      }
                    >
                      {row.title}
                    </span>
                  </label>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    disabled={busy}
                    aria-label={`Delete ${row.title}`}
                    onClick={() => save.runAsync({ rawInput: { kind: "delete", id: row.id } })}
                  >
                    Delete
                  </Button>
                </li>
              ))}
            </ul>
          )}
          <p className="mt-5 text-xs text-muted-foreground">
            {rows.filter((row) => row.done).length} of {rows.length} done. Changes are saved in your
            account.
          </p>
        </CardContent>
      </Card>
    </main>
  );
}

import { createFileRoute, redirect } from "@tanstack/react-router";
import { Todos } from "../frontend/Todos.tsx";
export const Route = createFileRoute("/todos")({
  gcTime: 0,
  beforeLoad: async ({ context }) => {
    if ((await context.account()) === null) throw redirect({ to: "/" });
    await context.bootstrap();
  },
  component: Todos,
});

import { createServerFn } from "@tanstack/react-start";
import { setResponseHeader } from "@tanstack/react-start/server";
import { listTodos, changeTodo } from "../backend/index.ts";
import { readTodoCommand } from "../contracts/commands.ts";
import { startRequests } from "@tinker/start";
import { readResult } from "@tinker/start/server";
import { readReceipt } from "./result.server.ts";
export const getTodos = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) => {
    setResponseHeader("Cache-Control", "no-store");
    return readResult(await context.session.settle(listTodos, { signal: context.signal }));
  });
export const updateTodo = createServerFn({ method: "POST" })
  .middleware([startRequests.middleware])
  .validator(readTodoCommand)
  .handler(async ({ context, data }) =>
    readReceipt(await context.session.settle(changeTodo, { input: data, signal: context.signal })),
  );
